import os, socket, subprocess, sys, time, urllib.request

ASSETS = ["app.css", "app.js", "index.html", "logo.svg", "vendor.js"]

def wait_ready(path, timeout=5):
    t0 = time.time()
    while time.time() - t0 < timeout:
        if os.path.exists(path):
            return open(path).read().strip()
        time.sleep(0.03)
    return None

for run in [0, 1, 2, 3, 4, 5, 6]:
    if os.path.exists(".server_ready"):
        os.remove(".server_ready")
    proc = subprocess.Popen([sys.executable, "scripts/dev_server.py", str(run)])
    port = wait_ready(".server_ready")
    try:
        print("===== RUN=%d port=%s =====" % (run, port))
        for name in ASSETS:
            tries = []
            for k in range(3):
                try:
                    urllib.request.urlopen(
                        "http://127.0.0.1:%s/%s" % (port, name), timeout=3).read()
                    tries.append("OK")
                except Exception as e:
                    tries.append(type(e).__name__)
            print("  %-11s %s" % (name, " ".join(tries)))
    finally:
        proc.kill()
        proc.wait()
    if os.path.exists(".server_ready"):
        os.remove(".server_ready")

